mapper.select:
SELECT t.bld_id, t.lat, t.lng, t.score, t.bld_nm, t.addr, t.use_nm, t.vuln_hh_cnt, t.checked
  FROM (

	   AND b.lat BETWEEN #{minLat} AND #{maxLat}
	   AND b.lng BETWEEN #{minLng} AND #{maxLng}
  ) t
 ORDER BY t.score DESC, t.vuln_hh_cnt DESC, t.priority_sum DESC, t.bld_id
 LIMIT #{limit}

SELECT COUNT(*)
  FROM (


	AND (b.addr LIKE CONCAT('%', #{q}, '%') OR b.bld_nm LIKE CONCAT('%', #{q}, '%'))
  ) t
 WHERE t.score >= #{scoreMin}
